          setTableCarts(prev => {
            const mergedCarts = { ...prev };
            let hasChanged = false;

            Object.keys(stateData.tableCarts || {}).forEach(tableId => {
              const isCurrentlyEditing = selectedTable && String(selectedTable.id) === String(tableId);
              if (isCurrentlyEditing) return;

              const incomingCart = stateData.tableCarts[tableId];
              const currentCart = prev[tableId];

              if (JSON.stringify(currentCart) !== JSON.stringify(incomingCart)) {
                mergedCarts[tableId] = incomingCart;
                hasChanged = true;
              }
            });

            Object.keys(prev).forEach(tableId => {
              if (!(stateData.tableCarts || {})[tableId]) {
                const isCurrentlyEditing = selectedTable && String(selectedTable.id) === String(tableId);
                if (!isCurrentlyEditing) {
                  delete mergedCarts[tableId];
                  hasChanged = true;
                }
              }
            });

            if (hasChanged) {
              localStorage.setItem('pos_table_carts', JSON.stringify(mergedCarts));
              return mergedCarts;
            }
            return prev;
          });
        }"

